const b = $json.body ?? $json;
const txt = (v, max) => String(v ?? '').trim().slice(0, max);
const entero = (v) => Number.parseInt(v, 10) || 0;
const fecha = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v ?? '')) ? String(v) : '';
const accion = txt(b.accion ?? b.action, 40).toLowerCase();
const session_token = txt(b.session_token, 200);

const FRONTEND_URL = 'http://localhost:3000'; // cámbialo cuando tengas dominio
const ACCIONES = ['dashboard', 'monitoreo', 'tickets_admin', 'trazabilidad', 'accesos', 'kb_listar', 'kb_guardar',
                  'tecnicos_listar', 'tecnico_guardar', 'ausencia_guardar', 'ausencia_eliminar', 'zona_guardar'];
const ESTADOS = ['Pendiente', 'En diagnóstico', 'Resuelto IA', 'Escalamiento pendiente', 'Escalado nivel 2',
                 'Pendiente de asignación', 'Agendado', 'En atención', 'Pendiente de confirmación', 'Cerrado', 'Cancelado'];
const PRIORIDADES = ['Crítica', 'Alta', 'Media', 'Baja'];

// Periodo por defecto: últimos 30 días (hora Colombia); máximo un año
const hoy = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Bogota' }));
const iso = (f) => `${f.getFullYear()}-${String(f.getMonth() + 1).padStart(2, '0')}-${String(f.getDate()).padStart(2, '0')}`;
const hace30 = new Date(hoy); hace30.setDate(hoy.getDate() - 29);
let desde = fecha(b.desde) || iso(hace30);
let hasta = fecha(b.hasta) || iso(hoy);
if (desde > hasta) [desde, hasta] = [hasta, desde];
if ((new Date(hasta) - new Date(desde)) / 864e5 > 366) {
  const d = new Date(hasta); d.setDate(d.getDate() - 366); desde = iso(d);
}

const datos = {
  accion, session_token, desde, hasta,
  estado: ESTADOS.includes(b.estado) ? b.estado : '',
  prioridad: PRIORIDADES.includes(b.prioridad) ? b.prioridad : '',
  texto: txt(b.texto, 100),
  solo_vencidos: b.solo_vencidos === true || b.solo_vencidos === 'true',
  pagina: Math.max(1, entero(b.pagina)),
  tamano: Math.min(100, Math.max(5, entero(b.tamano) || 25)),
  ticket_id: entero(b.ticket_id),
  correo: txt(b.correo, 254).toLowerCase(),
  evento: txt(b.evento, 30),
  kb_id: entero(b.id),
  titulo: txt(b.titulo, 250),
  categoria: txt(b.categoria, 80),
  contenido: txt(b.contenido, 8000),
  activo: !(b.activo === false || b.activo === 'false'),
  creado_desde: fecha(b.creado_desde),
  creado_hasta: fecha(b.creado_hasta),
  // técnicos
  tec_id: entero(b.tecnico_id),
  nombre: txt(b.nombre, 150),
  correo_tecnico: txt(b.correo_tecnico, 254).toLowerCase(),
  telefono: txt(b.telefono, 30),
  zona: txt(b.zona, 12),
  hora_inicio: Number.parseInt(b.hora_inicio, 10),
  hora_fin: Number.parseInt(b.hora_fin, 10),
  dias: [...new Set((Array.isArray(b.dias) ? b.dias : []).map(Number))].filter((n) => n >= 1 && n <= 7).sort(),
  // ausencias
  ausencia_id: entero(b.ausencia_id),
  aus_desde: fecha(b.aus_desde),
  aus_hasta: fecha(b.aus_hasta),
  motivo: txt(b.motivo, 200),
  // zonas
  zona_id: entero(b.zona_id),
  palabras_clave: txt(b.palabras_clave, 2000),
  frontend_url: FRONTEND_URL,
};

let error = '', status = 'invalid';
if (!ACCIONES.includes(accion)) error = 'Acción no válida.';
else if (!session_token) { error = 'Inicia sesión para continuar.'; status = 'unauthorized'; }
else if (accion === 'trazabilidad' && !datos.ticket_id && !datos.correo) error = 'Escribe un número de ticket o un correo.';
else if (accion === 'kb_guardar' && datos.titulo.length < 5) error = 'El título debe tener al menos 5 caracteres.';
else if (accion === 'kb_guardar' && datos.contenido.length < 20) error = 'El contenido debe tener al menos 20 caracteres.';
else if (accion === 'tecnico_guardar' && datos.nombre.length < 3) error = 'Escribe el nombre del técnico.';
else if (accion === 'tecnico_guardar' && !datos.tec_id && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(datos.correo_tecnico)) error = 'Escribe un correo válido para el técnico.';
else if (accion === 'tecnico_guardar' && !datos.zona) error = 'Selecciona la zona de atención.';
else if (accion === 'tecnico_guardar' && !(datos.hora_inicio >= 0 && datos.hora_fin <= 24 && datos.hora_fin > datos.hora_inicio)) error = 'El horario no es válido: la hora final debe ser mayor que la inicial.';
else if (accion === 'tecnico_guardar' && !datos.dias.length) error = 'Selecciona al menos un día laboral.';
else if (accion === 'ausencia_guardar' && (!datos.tec_id || !datos.aus_desde || !datos.aus_hasta || datos.aus_hasta < datos.aus_desde)) error = 'Indica el técnico y un rango de fechas válido.';
else if (accion === 'ausencia_eliminar' && !datos.ausencia_id) error = 'Ausencia no válida.';
else if (accion === 'zona_guardar' && (datos.zona.length < 2 || datos.zona.length > 12)) error = 'El nombre de la zona debe tener entre 2 y 12 caracteres.';

return [{ json: { ...datos, ruta: error ? 'invalido' : 'sesion', error, status } }];

const req = $('Validar petición de gestión').first().json;
const s = $input.first().json;
const permisos = {"dashboard": ["admin"], "tickets_admin": ["admin"], "trazabilidad": ["admin"], "accesos": ["admin"], "kb_listar": ["admin"], "kb_guardar": ["admin"], "monitoreo": ["admin"], "tecnicos_listar": ["admin"], "tecnico_guardar": ["admin"], "ausencia_guardar": ["admin"], "ausencia_eliminar": ["admin"], "zona_guardar": ["admin"]};
let ruta = req.accion, status = 'ok', message = '';
if (!s.usuario_id) {
  ruta = 'denegado'; status = 'unauthorized'; message = 'Tu sesión expiró o no es válida. Inicia sesión nuevamente.';
} else if (!(permisos[req.accion] || []).includes(s.rol)) {
  ruta = 'denegado'; status = 'forbidden'; message = 'Tu cuenta no tiene permiso para esta acción.';
} else if (s.rol === 'tecnico' && !s.tecnico_id) {
  ruta = 'denegado'; status = 'forbidden'; message = 'Tu usuario técnico no está activo en la tabla de técnicos.';
}
return [{ json: { ...req, ruta, status, message,
  auth_usuario_id: Number(s.usuario_id || 0), auth_nombre: s.nombre_completo || '', auth_correo: s.correo || '',
  auth_rol: s.rol || '', auth_tecnico_id: Number(s.tecnico_id || 0) } }];

