WITH ins AS (
  INSERT INTO public.base_conocimiento (titulo, categoria, contenido, activo)
  SELECT $2, NULLIF($3, ''), $4, $5 WHERE $1 = 0
  RETURNING id
), upd AS (
  UPDATE public.base_conocimiento SET titulo = $2, categoria = NULLIF($3, ''), contenido = $4, activo = $5
   WHERE id = $1 AND $1 <> 0
  RETURNING id
)
SELECT COALESCE((SELECT id FROM ins), (SELECT id FROM upd)) AS id;
